#include <iostream>
using namespace std;

int main()
{
    int number;

    cout << "Enter a number: ";
    cin >> number;

    if (number > 0)
    {
        cout << "Positive" << endl;
    }
    else
    {
        cout << "Not positive" << endl;
    }
}

#include <iostream>
using namespace std;

int main()
{

    int a = 5, b = 8;

    cout << (a < b) << endl;  // prints 1 (true)
    cout << (a == b) << endl; // prints 0 (false)

    string name = "Nathan";
    cout << (name == "Nathan") << endl;
    cout << (name != "Nathan") << endl;

    return 0;
}
